// KALYPSO site: the live window, downloads from the latest release, and small touches.
// Everything works without the GitHub API; it only fills in real files and stars when it can.

const REPO = "kalyppso/kalypso";
document.documentElement.classList.add("js");
const $ = (s, el = document) => el.querySelector(s);
const $$ = (s, el = document) => [...el.querySelectorAll(s)];
const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;

/* ---------- The live window ---------- */

// Click around: each sidebar item shows its panel.
$$(".ws-nav button").forEach((b) =>
  b.addEventListener("click", () => {
    $$(".ws-nav button").forEach((x) => x.classList.toggle("on", x === b));
    $$(".panel").forEach((p) => p.classList.toggle("on", p.dataset.panel === b.dataset.panel));
  }),
);

// The shape of a real run, as the Claude Agent SDK runtime writes it to the transcript.
const DEMO = [
  ["status", "started · claude-sonnet-5-5 · 22 tools", 500],
  ["text", "I'll run the tests first to see what fails.", 900],
  ["tool", "Bash|npm test", 700, 0.012],
  ["output", "23 passing, 1 failing: parses an empty config file", 900],
  ["tool", "Read|src/config.ts", 600, 0.018],
  ["tool", "Edit|src/config.ts", 900, 0.027],
  ["tool", "Bash|npm test", 700, 0.012],
  ["output", "24 passing", 900],
  ["tool", "Bash|git push --force origin main", 800, 0.009],
  ["policy", 'Blocked by policy <b>"No force-push to main"</b>. The command never ran.', 1500, 0, true],
  ["text", "Force-pushing to main isn't allowed here. I'll push a branch and open a pull request instead.", 1000, 0.015],
  ["tool", "Bash|git push origin fix/empty-config", 800, 0.009],
  ["tool", "Bash|gh pr create --fill", 900, 0.012],
  ["output", "https://github.com/acme/app/pull/482", 700],
  ["result", "Done · 9 turns · $0.042", 4500],
];

(function demo() {
  const log = $("#demo-log");
  if (!log) return;
  const status = $("#demo-status");
  const esc = (t) => t.replace(/&/g, "&amp;").replace(/</g, "&lt;");
  let i = 0, spend = 0.84, blocked = 0, timer = null, visible = false;
  const meters = () => {
    $("#demo-spend").textContent = `$${spend.toFixed(2)}`;
    $("#demo-meter").style.width = `${Math.min(100, (spend / 5) * 100)}%`;
    $("#demo-blocked-row").textContent = `${blocked} today`;
  };
  const line = ([kind, text], animate = true) => {
    const li = document.createElement("li");
    li.className = `k-${kind}${animate ? " new" : ""}`;
    if (kind === "tool") { const [tool, arg] = text.split("|"); li.innerHTML = `<b>${tool}</b>${esc(arg)}`; }
    else if (kind === "policy") li.innerHTML = text;
    else li.textContent = text;
    log.append(li);
    while (log.children.length > 24) log.firstElementChild.remove();
  };
  const apply = (s) => {
    spend += s[3] || 0;
    if (s[4]) blocked += 1;
    if (s[0] === "result") { status.classList.add("done"); status.lastChild.textContent = "Waiting for a message"; }
    meters();
  };
  const reset = () => {
    log.replaceChildren(); i = 0; spend = 0.84; blocked = 0;
    status.classList.remove("done"); status.lastChild.textContent = "Running"; meters();
  };
  const step = () => {
    timer = null;
    if (!visible) return;
    if (i >= DEMO.length) { reset(); timer = setTimeout(step, 600); return; }
    const s = DEMO[i++];
    line(s); apply(s);
    timer = setTimeout(step, s[2]);
  };
  if (matchMedia("(prefers-reduced-motion: reduce)").matches) {
    DEMO.forEach((s) => { line(s, false); apply(s); });
    return;
  }
  meters();
  new IntersectionObserver(([e]) => {
    visible = e.isIntersecting;
    if (visible && !timer) timer = setTimeout(step, 400);
  }).observe($(".stage"));
})();

/* ---------- Downloads ---------- */

const PICK = {
  exe: (n) => /\.exe$/i.test(n),
  msi: (n) => /\.msi$/i.test(n),
  dmg: (n) => /\.dmg$/i.test(n),
  appimage: (n) => /\.appimage$/i.test(n),
  deb: (n) => /\.deb$/i.test(n),
  rpm: (n) => /\.rpm$/i.test(n),
};
const MAIN = { windows: "exe", mac: "dmg", linux: "appimage" };
const NAME = { windows: "Windows", mac: "macOS", linux: "Linux" };
const macArch = (name) => (/universal/i.test(name) ? "Apple silicon and Intel" : /aarch64|arm64/i.test(name) ? "Apple silicon" : /x64|x86_64/i.test(name) ? "Intel" : "");

function platform() {
  const ua = navigator.userAgent;
  if (/Windows/i.test(ua)) return "windows";
  if (/Macintosh|Mac OS X/i.test(ua) && !/iPhone|iPad/i.test(ua)) return "mac";
  if (/Linux/i.test(ua) && !/Android/i.test(ua)) return "linux";
  return null;
}

async function latestRelease() {
  // The list includes pre-releases, which /releases/latest skips; 0.x builds are pre-releases.
  const res = await fetch(`https://api.github.com/repos/${REPO}/releases?per_page=10`, { headers: { Accept: "application/vnd.github+json" } });
  if (!res.ok) throw new Error(String(res.status));
  return (await res.json()).find((r) => !r.draft && r.assets.length) ?? null;
}

(async () => {
  const os = platform();
  if (os) {
    $(`.oses li[data-os="${os}"]`)?.classList.add("mine");
    $("#hero-label").textContent = `Download for ${NAME[os]}`;
  }
  let release = null;
  try { release = await latestRelease(); } catch { /* offline or rate-limited: links stay on the releases page */ }
  if (!release) return;
  for (const a of $$(".oses a[data-asset]")) {
    const asset = release.assets.find((x) => PICK[a.dataset.asset](x.name));
    if (asset) { a.href = asset.browser_download_url; a.title = asset.name; } else a.hidden = true;
  }
  const dmg = release.assets.find((x) => PICK.dmg(x.name));
  if (dmg && macArch(dmg.name)) $("#mac-arch").textContent = macArch(dmg.name);
  const mine = os && release.assets.find((x) => PICK[MAIN[os]](x.name));
  if (mine) {
    $("#hero-download").href = mine.browser_download_url;
    $$("[data-dl]").forEach((a) => (a.href = mine.browser_download_url));
  }
  const when = new Date(release.published_at).toLocaleDateString(undefined, { month: "long", day: "numeric", year: "numeric" });
  $("#release-line").textContent = `${release.tag_name}, ${when}. No account, no telemetry. Needs Docker or Podman.`;
})();

// Stars: shown only once the number means something.
fetch(`https://api.github.com/repos/${REPO}`)
  .then((r) => (r.ok ? r.json() : null))
  .then((repo) => {
    if (!repo || !(repo.stargazers_count >= 50)) return;
    $$("[data-stars]").forEach((el) => { el.textContent = repo.stargazers_count.toLocaleString(); el.hidden = false; });
  })
  .catch(() => {});

/* ---------- Page chrome ---------- */

const sentinel = document.createElement("div");
sentinel.style.cssText = "position:absolute;top:0;height:1px;width:1px";
document.body.prepend(sentinel);
new IntersectionObserver(([e]) => $(".nav").classList.toggle("scrolled", !e.isIntersecting)).observe(sentinel);

const io = new IntersectionObserver(
  (entries) => {
    for (const e of entries) if (e.isIntersecting) { e.target.classList.add("in"); io.unobserve(e.target); }
  },
  { rootMargin: "0px 0px -10% 0px" },
);
$$(".three, .get, .faq").forEach((el) => { el.classList.add("reveal"); io.observe(el); });

/* ---------- The section you're in ---------- */

(function navActive() {
  const links = $$('.nav-link[href^="#"]');
  const targets = links.map((a) => $(a.getAttribute("href"))).filter(Boolean);
  if (!targets.length) return;
  // The section crossing the upper middle of the screen is the one you're in.
  const watch = new IntersectionObserver(
    (entries) => {
      for (const e of entries) {
        if (!e.isIntersecting) continue;
        links.forEach((a) => a.classList.toggle("on", a.getAttribute("href") === `#${e.target.id}`));
      }
    },
    { rootMargin: "-40% 0px -55% 0px" },
  );
  targets.forEach((t) => watch.observe(t));
})();

/* ---------- The island: point at a layer ---------- */

(function isle() {
  const box = $(".isle");
  if (!box) return;
  const map = $("#isle", box);
  const note = $("#isle-note", box);
  const SAY = {
    sandbox: "Sandbox: the agent runs in its own box and only reaches hosts you allowed.",
    policies: "Policies: every tool call is checked against your rules. Risky ones wait for you.",
    vault: "Vault: the stand-in key is swapped for the real one here, never inside the sandbox.",
    gateway: "Gateway: every model call is metered and stops at the budget you set.",
  };
  const IDLE = note.textContent;
  // Point at a ring: it lights up and the note says what that layer does.
  const pick = (key) => {
    if (key) box.dataset.on = key; else delete box.dataset.on;
    note.textContent = key ? SAY[key] : IDLE;
    note.classList.toggle("on", !!key);
  };
  const layerOf = (e) => e.target.closest("[data-layer]")?.dataset.layer || null;
  map.addEventListener("mouseover", (e) => pick(layerOf(e)));
  map.addEventListener("mouseleave", () => pick(null));
  map.addEventListener("focusin", (e) => pick(layerOf(e)));
  map.addEventListener("focusout", () => pick(null));
  map.addEventListener("click", (e) => pick(layerOf(e))); // touch
  // The calls only move while the map is on screen, and never with reduced motion.
  if (reduce) { map.pauseAnimations(); return; }
  new IntersectionObserver(([e]) => (e.isIntersecting ? map.unpauseAnimations() : map.pauseAnimations())).observe(map);
})();

/* ---------- Kalypso, drawn in code ----------
   She is a set of polylines traced once from the logo (the centreline of every stroke),
   stroked on a canvas as clean vector lines. Her head is modelled as a rough ellipsoid, so
   she turns toward the cursor in 3D; lines near the cursor bend away from it. She is drawn
   in from the bottom on load, and a scanline passes over her now and then. */

(function kalypso() {
  const fig = $(".portrait");
  const cv = $("#kalypso");
  if (!fig || !cv) return;
  const K = {"w":790,"h":1090,"lines":"","eyes":[[518,512],[635,513]],"stars":[[110,413],[195,452],[96,457],[77,864],[186,787],[700,869],[528,957],[243,982],[387,1064],[387,865]],"head":{"cx":510,"cy":450,"rx":250,"ry":330}};
  const ctx = cv.getContext("2d");
  const fine = matchMedia("(pointer: fine)").matches;

  // Unpack: per polyline, a count, the first point (uint16 x, y), then int8 steps.
  const raw = Uint8Array.from(atob(K.lines), (c) => c.charCodeAt(0));
  const dv = new DataView(raw.buffer);
  const xs = [], ys = [], starts = [];
  for (let o = 0; o < raw.length;) {
    const n = dv.getUint16(o, true); let x = dv.getUint16(o + 2, true), y = dv.getUint16(o + 4, true); o += 6;
    starts.push(xs.length); xs.push(x); ys.push(y);
    for (let k = 1; k < n; k++, o += 2) { x += dv.getInt8(o); y += dv.getInt8(o + 1); xs.push(x); ys.push(y); }
  }
  starts.push(xs.length);
  const nv = xs.length, hd = K.head, cx0 = K.w / 2, cy0 = K.h / 2;
  const depth = (x, y) => { const dx = (x - hd.cx) / hd.rx, dy = (y - hd.cy) / hd.ry, q = 1 - dx * dx - dy * dy; return q > 0 ? Math.sqrt(q) * hd.rx * 0.55 : 0; };
  const PX = Float32Array.from(xs, (x) => x - cx0), PY = Float32Array.from(ys, (y) => y - cy0);
  const PZ = Float32Array.from(xs, (x, i) => depth(x, ys[i]));
  const QX = new Float32Array(nv), QY = new Float32Array(nv);

  let W = 0, H = 0, dpr = 1, s = 1;
  let rx = 0, ry = 0, tx = 0, ty = 0; // turn, -1..1
  let mx = -1e5, my = -1e5; // cursor, in CSS pixels on the canvas
  let t0 = 0, raf = null, visible = true, last = 0;

  const size = () => {
    dpr = Math.min(2, devicePixelRatio || 1);
    W = fig.clientWidth;
    H = W * (K.h / K.w);
    cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
    cv.style.height = H + "px";
    s = W / K.w;
  };

  const place = (x, y, z, cyr, syr, cxr, sxr) => {
    const X = x * cyr + z * syr, Z1 = -x * syr + z * cyr;
    return [(X + cx0) * s, (y * cxr - Z1 * sxr + cy0) * s];
  };

  const draw = (now) => {
    const t = now - t0;
    const ay = rx * 0.3, ax = -ry * 0.18;
    const cyr = Math.cos(ay), syr = Math.sin(ay), cxr = Math.cos(ax), sxr = Math.sin(ax);
    const R = 60, R2 = R * R, PUSH = 14;
    for (let i = 0; i < nv; i++) {
      const x = PX[i], y = PY[i], z = PZ[i];
      const X = x * cyr + z * syr, Z1 = -x * syr + z * cyr;
      let px = (X + cx0) * s, py = (y * cxr - Z1 * sxr + cy0) * s;
      const dx = px - mx, dy = py - my, d2 = dx * dx + dy * dy;
      if (d2 < R2) { const d = Math.sqrt(d2) || 1, f = (1 - d / R); const p = f * f * PUSH; px += (dx / d) * p; py += (dy / d) * p; }
      QX[i] = px; QY[i] = py;
    }
    const path = new Path2D();
    for (let k = 0; k < starts.length - 1; k++) {
      const a = starts[k], b = starts[k + 1];
      path.moveTo(QX[a], QY[a]);
      for (let i = a + 1; i < b; i++) path.lineTo(QX[i], QY[i]);
    }
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, W, H);
    ctx.lineJoin = ctx.lineCap = "round";
    // Drawn in from the bottom: everything below the rising edge, and the edge itself lit.
    const rise = reduce ? 1 : Math.min(1, t / 1700);
    const edge = H * (1 - (1 - (1 - rise) ** 3));
    ctx.save();
    ctx.beginPath(); ctx.rect(0, edge, W, H - edge); ctx.clip();
    ctx.lineWidth = 0.75;
    ctx.strokeStyle = "rgba(236,236,240,0.82)";
    ctx.stroke(path);
    ctx.restore();
    const lit = (y0, h, a) => {
      ctx.save(); ctx.beginPath(); ctx.rect(0, y0, W, h); ctx.clip();
      ctx.lineWidth = 1.1; ctx.strokeStyle = `rgba(255,255,255,${a})`; ctx.stroke(path); ctx.restore();
    };
    if (rise < 1) { lit(edge, 10, 1); return; }
    // A scanline every 8 seconds.
    const scan = reduce ? -1 : ((t - 2600) % 8000) / 1700;
    if (scan >= 0 && scan <= 1) lit(scan * H - 9, 18, 0.9);
    // Stars come and go; eyes catch the light and look toward the cursor.
    K.stars.forEach(([x, y], j) => {
      const [px, py] = place(x - cx0, y - cy0, 0, cyr, syr, cxr, sxr);
      const tw = 0.5 + 0.5 * Math.sin(now / 560 + j * 1.9);
      ctx.fillStyle = `rgba(255,255,255,${(0.25 + 0.75 * tw).toFixed(2)})`;
      ctx.beginPath(); ctx.arc(px, py, 1 + 1.4 * tw, 0, 7); ctx.fill();
    });
    ctx.fillStyle = "#fff";
    K.eyes.forEach(([x, y]) => {
      const [px, py] = place(x - cx0, y - cy0, depth(x, y), cyr, syr, cxr, sxr);
      ctx.beginPath(); ctx.arc(px + rx * 2.5, py + ry * 1.5, 2.2, 0, 7); ctx.fill();
    });
  };

  const loop = (now) => {
    raf = null;
    if (!visible) return;
    rx += (tx - rx) * 0.08;
    ry += (ty - ry) * 0.08;
    if (now - last > (fine ? 16 : 33)) { draw(now); last = now; }
    raf = requestAnimationFrame(loop);
  };
  const start = () => { if (!raf && !reduce) raf = requestAnimationFrame(loop); };

  if (fine && !reduce) {
    addEventListener("pointermove", (e) => {
      const b = cv.getBoundingClientRect();
      tx = Math.max(-1, Math.min(1, (e.clientX - (b.left + b.width / 2)) / (innerWidth / 2)));
      ty = Math.max(-1, Math.min(1, (e.clientY - (b.top + b.height * 0.42)) / (innerHeight / 2)));
      mx = e.clientX - b.left;
      my = e.clientY - b.top;
    }, { passive: true });
    document.documentElement.addEventListener("pointerleave", () => { tx = ty = 0; mx = my = -1e5; });
  }
  new ResizeObserver(() => { size(); if (reduce) draw(performance.now()); }).observe(fig);
  new IntersectionObserver(([e]) => { visible = e.isIntersecting; if (visible) start(); }).observe(cv);
  size();
  t0 = performance.now();
  if (reduce) draw(t0); else start();
})();

/* ---------- In the app: tabs over real screens ---------- */

(function showcase() {
  const tabs = $$(".show-tabs [role=tab]");
  if (!tabs.length) return;
  const row = $(".show-tabs");
  const panel = $("#show-panel");
  // Tabs change only when you pick one: nothing moves on its own while you scroll.
  const select = (i, focus = false) => {
    const current = (i + tabs.length) % tabs.length;
    const key = tabs[current].dataset.tab;
    tabs.forEach((t, n) => {
      t.setAttribute("aria-selected", String(n === current));
      t.tabIndex = n === current ? 0 : -1;
    });
    $$(".show-shot, .show-copy").forEach((el) => el.classList.toggle("on", el.dataset.tab === key));
    panel.setAttribute("aria-labelledby", tabs[current].id);
    if (focus) tabs[current].focus({ preventScroll: true });
    // Keep the chosen tab visible in its own row (phones), without moving the page.
    const t = tabs[current];
    if (t.offsetLeft < row.scrollLeft || t.offsetLeft + t.offsetWidth > row.scrollLeft + row.clientWidth)
      row.scrollTo({ left: t.offsetLeft - 8, behavior: reduce ? "auto" : "smooth" });
  };
  tabs.forEach((t, i) => t.addEventListener("click", () => select(i)));
  row.addEventListener("keydown", (e) => {
    const now = tabs.findIndex((t) => t.getAttribute("aria-selected") === "true");
    const go = { ArrowRight: now + 1, ArrowLeft: now - 1, Home: 0, End: tabs.length - 1 }[e.key];
    if (go === undefined) return;
    e.preventDefault();
    select(go, true);
  });
  select(0);
})();
